    INSERT INTO notices (id, title, body, priority, created_at) VALUES
      ('93618841-8a0f-4345-9aa0-a41d02523338', 'Water Supply Interruption on Sept 2nd', 'Municipal water supply will be interrupted on Wednesday, September 2nd from 10 AM to 2 PM for pipeline maintenance. Please store water in advance. We apologize for the inconvenience.', 'urgent', '2026-08-27T09:00:00Z'),
      ('4a80cb57-0ab8-4c00-9d47-3a449ff8188b', 'Monthly Maintenance Due Reminder', 'This is a reminder that maintenance bills are due on the 10th of every month. A late fee of Rs.5/day applies after the due date. Pay conveniently via the UPI QR code in the Payments section.', 'normal', '2026-08-24T08:30:00Z'),
      ('4d284e9d-e831-4495-bd3a-e3e7d1974087', 'Annual General Meeting (AGM) - September 14th', 'The Annual General Meeting will be held on Sunday, September 14th at 6:00 PM in the Clubhouse. Agenda includes annual budget review, committee elections, and upcoming maintenance projects. All owners are requested to attend.', 'normal', '2026-08-20T11:00:00Z'),
      ('c202a6d0-4039-4cb6-aed3-a21fca132f01', 'Independence Day Celebration - Thank You!', 'Thank you to all residents who joined the Independence Day flag hoisting and cultural program at the Clubhouse. Photos have been shared in the society WhatsApp group. See you at the next event!', 'normal', '2026-08-16T10:00:00Z'),
      ('e8a61a47-8bba-4724-b65e-0507d9cbf9e6', 'Parking Slot Re-allocation Notice', 'Basement parking slots will be re-allocated based on updated vehicle registrations. Please submit your vehicle RC copy to the society office by September 10th to retain your slot.', 'normal', '2026-08-12T14:00:00Z')
